WITH day AS (
  SELECT * FROM agg_placement_daily WHERE event_date = DATE '2017-05-09'
), m AS (
  SELECT MAX(ctr) AS max_ctr FROM day
)
SELECT d.event_date, d.placement_id, d.impressions, d.clicks, d.ctr
FROM day d JOIN m ON d.ctr = m.max_ctr;

